source = '''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    marker = min((value for value in counts if value != background), key=counts.get)
    marked = [[False] * w for _ in range(h)]
    for r, row in enumerate(grid):
        cols = [c for c, value in enumerate(row) if value == marker]
        if len(cols) >= 2:
            for c in range(cols[0] + 1, cols[-1]):
                marked[r][c] = True
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        if len(rows) >= 2:
            for r in range(rows[0] + 1, rows[-1]):
                marked[r][c] = True
    return [[3 if marked[r][c] and grid[r][c] == background else grid[r][c]
             for c in range(w)] for r in range(h)]
'''
